export async function loadRamps(url: string, signal?: AbortSignal): Promise<Ramp[]> {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`HTTP ${response.status}: could not load ramps`);
  const data: unknown = await response.json();
  if (!Array.isArray(data) || !data.every(item =>
    typeof item === 'object' && item !== null &&
    typeof item.id === 'string' && typeof item.name === 'string'
  )) throw new Error('Invalid ramp data');
  return data as Ramp[];
}

// Vite serves public files at /; Sandpack's static-file service worker uses /public/.
// Both requests stay on the preview origin. Do not retry intentional aborts.
export async function loadLocalRamps(url: string, signal?: AbortSignal): Promise<Ramp[]> {
  try {
    return await loadRamps(url, signal);
  } catch (error) {
    if (url !== '/ramps.json' || signal?.aborted) throw error;
    return loadRamps('/public/ramps.json', signal);
  }
}

solution./styles.css:
:root { font-family: system-ui, sans-serif; color: #172c45; background: #f3f6fa; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 52rem; margin: 0 auto; padding: 1.5rem; }
h1 { font-size: 1.65rem; }
h2 { font-size: 1.15rem; }
section, article { background: white; border: 1px solid #cbd5e1; border-radius: .65rem; padding: 1rem; margin-block: 1rem; }
button, input, select { font: inherit; padding: .5rem .75rem; }
button { cursor: pointer; border: 1px solid #54708c; border-radius: .3rem; background: #edf4ff; color: #172c45; }
button:disabled { cursor: default; opacity: .55; }
:focus-visible { outline: 3px solid #0064d9; outline-offset: 3px; }
.controls { display: flex; flex-wrap: wrap; align-items: center; gap: .75rem; margin-block: 1rem; }
output { font-size: 1.4rem; font-weight: 700; }
li { margin-block: .5rem; }
label { display: inline-flex; align-items: center; gap: .5rem; }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; border-bottom: 1px solid #cbd5e1; padding: .6rem .3rem; }
code { overflow-wrap: anywhere; }
[role="alert"] { color: #a31515; }

